import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import { DEFAULT_AI_SETTINGS, type AiSettings, type AiProviderConfig, type WriterSettings, type ApparatusSettings, type RoomSettings } from "../types";
import { loadAiSettingsFromIdb, saveAiSettingsToIdb, loadWriterSettingsFromIdb, saveWriterSettingsToIdb, loadApparatusSettingsFromIdb, saveApparatusSettingsToIdb } from "./idb";
import { loadRoomSettingsLocally, saveRoomSettingsLocally } from "./convex-sync";
import { readThemePreference, writeThemePreference, applyTheme, normalizeThemePreference } from "./theme";
import { portablePreference, type PreferenceKind, type PreferenceValue } from "./account-preferences-contract";
import { createPreferenceSync } from "./preference-sync-engine";
import { readJournal, writeJournal, preferenceOwner, setPreferenceOwner, PREFERENCES_CHANGED, PREFERENCES_APPLIED } from "./preference-outbox";
import { reportApplicationError } from "./application-diagnostics";

async function readLocal(kind: PreferenceKind): Promise<PreferenceValue> {
  const value = kind === "writer" ? await loadWriterSettingsFromIdb()
    : kind === "ai" ? (await loadAiSettingsFromIdb() ?? DEFAULT_AI_SETTINGS)
    : kind === "apparatus" ? await loadApparatusSettingsFromIdb()
    : kind === "room" ? await loadRoomSettingsLocally() : readThemePreference();
  return portablePreference(kind, value);
}
async function applyLocal(kind: PreferenceKind, value: PreferenceValue) {
  if (kind === "writer") await saveWriterSettingsToIdb(value as unknown as WriterSettings, false);
  if (kind === "apparatus") {
    const local = await loadApparatusSettingsFromIdb();
    await saveApparatusSettingsToIdb({ ...local, ...value } as ApparatusSettings, false);
  }
  if (kind === "ai") {
    const local = await loadAiSettingsFromIdb() ?? DEFAULT_AI_SETTINGS;
    const remote = value as unknown as AiSettings;
    const providers = remote.providers.map(provider => {
      const device = local.providers.find(p => p.id === provider.id && p.type === provider.type);
      return { ...device, ...provider, apiKey: device?.apiKey ?? "", baseUrl: device?.baseUrl } as AiProviderConfig;
    });
    await saveAiSettingsToIdb({ ...local, ...remote, providers, judgement: remote.judgement ? { ...local.judgement, ...remote.judgement } : undefined }, false);
  }
  if (kind === "room") await saveRoomSettingsLocally(value as unknown as RoomSettings, false);
  if (kind === "appearance") {
    const preference = normalizeThemePreference(value);
    writeThemePreference(preference, false);
    applyTheme(preference, document.documentElement, window.matchMedia("(prefers-color-scheme: dark)").matches);
  }
  window.dispatchEvent(new CustomEvent(PREFERENCES_APPLIED, { detail: { kind } }));
}

export function startAccountPreferences(client: ConvexClient, account: string) {
  const previousOwner = preferenceOwner();
  const seed = !previousOwner || previousOwner === account;
  setPreferenceOwner(account);
  // Anonymous changes seed an empty account, but never replace an existing
  // account's preferences simply because this is a new device.
  const engine = createPreferenceSync({
    seed, readLocal, applyLocal,
    readJournal: () => readJournal(account),
    writeJournal: journal => writeJournal(account, journal),
    pull: () => client.query(api.preferences.list, {}),
    put: row => client.mutation(api.preferences.put, { kind: row.kind, json: row.json, expectedRevision: row.revision }),
    onError: error => reportApplicationError("twyne:preferences-sync", error, {
