      const q = raw as { type: string; criteria?: string[] | Record<string, null> };
      if (q.type === "noul") return [id, { type: "noul", noul: 0.9 }];
      const labels = Array.isArray(q.criteria) ? q.criteria : Object.keys(q.criteria!);
      const last = labels.length - 1;
      return [id, q.type === "score" ? {
        type: "score", score: last, confidence: 1,
        probabilities: Object.fromEntries(labels.map((_, i) => [i, i === last ? 1 : 0])),
        legend: Object.fromEntries(labels.map((label, i) => [i, label])),
      } : {
        type: "choice", choice: labels[0], confidence: 1,
        probabilities: Object.fromEntries(labels.map((label, i) => [label, i === 0 ? 1 : 0])),
